(145, 1, '2026-02-27 05:38:17', '2026-02-27 05:38:17', '<!-- wp:acf/introtext-section {\"name\":\"acf/introtext-section\",\"data\":{\"get_dynamic_heading_from_page_post\":\"1\",\"_get_dynamic_heading_from_page_post\":\"field_69a16b0f69a0f\",\"heading_text\":\"CONTACT\",\"_heading_text\":\"field_69a16b5869a10\",\"heading_level\":\"h1\",\"_heading_level\":\"field_69a16b7269a11\",\"content\":\"Hetton is a small hamlet, approximately six miles from the historic town of Skipton in the heart of The Yorkshire Dales National Park. The Angel Inn can be found in the centre of the village.\",\"_content\":\"field_69a16bf469a12\",\"intro_section_bg\":\"\",\"_intro_section_bg\":\"field_69a16c1a69a13\",\"intro_section_button\":\"\",\"_intro_section_button\":\"field_69a16c7e69a14\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"120\",\"right\":\"\",\"bottom\":\"60\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"120\",\"right\":\"\",\"bottom\":\"50\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"100\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\",\"content_alignment\":\"left\",\"_content_alignment\":\"field_69a6e5f3c5f77\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/contact-details-with-image-section {\"name\":\"acf/contact-details-with-image-section\",\"data\":{\"address_heading_text\":\"ADDRESS\",\"_address_heading_text\":\"field_69aff2ef17207\",\"address_heading_level\":\"h3\",\"_address_heading_level\":\"field_69aff4187ae2e\",\"address_contact_details_0_icon\":80,\"_address_contact_details_0_icon\":\"