\":\"\",\"_intro_section_button\":\"field_69a16c7e69a14\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"60\",\"right\":\"\",\"bottom\":\"60\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"50\",\"right\":\"\",\"bottom\":\"50\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"40\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\",\"content_alignment\":\"left\",\"_content_alignment\":\"field_69a6e5f3c5f77\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/career-post-listing-section {\"name\":\"acf/career-post-listing-section\",\"data\":{\"select_post_type\":\"post\",\"_select_post_type\":\"field_69ae771a6c76f\",\"posts_per_page\":\"4\",\"_posts_per_page\":\"field_69ae77c8c662b\",\"posts_per_page_mobile\":\"4\",\"_posts_per_page_mobile\":\"field_69b161ef7f27b\",\"orderby\":\"date\",\"_orderby\":\"field_69ae77e1c662c\",\"order\":\"DESC\",\"_order\":\"field_69ae77fac662d\",\"section_bg\":\"\",\"_section_bg\":\"field_69ae781b4b40c\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_margin\":\"field_69ae78304b40d\",\"padding\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"50\",\"left\":\"\",\"linked\":\"0\",\"unit\"