(154, 1, '2026-02-27 05:46:49', '2026-02-27 05:46:49', '<!-- wp:acf/full-width-title-banner-image-section {\"name\":\"acf/full-width-title-banner-image-section\",\"data\":{\"banner_image\":688,\"_banner_image\":\"field_69bba0688316f\",\"section_bg\":\"\",\"_section_bg\":\"field_69bba06886d28\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69bba0688a684\",\"padding\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_padding\":\"field_69bba0688e295\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/introtext-section {\"name\":\"acf/introtext-section\",\"data\":{\"get_dynamic_heading_from_page_post\":\"0\",\"_get_dynamic_heading_from_page_post\":\"field_69a16b0f69a0f\",\"heading_text\":\"LOCATION\",\"_heading_text\":\"field_69a16b5869a10\",\"heading_level\":\"h1\",\"_heading_level\":\"field_69a16b7269a11\",\"content\":\"The Angel is a modern fine dining restaurant housed within the stunning surroundings of a 15th century inn at the heart of a beautiful Yorkshire Dales village. There has been an inn at the heart of this quiet Yorkshire village since the 15th century. The village is on the southern edge of the Yorkshire Dales and makes the perfect base for exploring. The bustling market towns of Skipton and Grassington are just a short drive away.\",\"_content\":\"field_69a16bf469a12\",\"intro_section_bg\":\"\",\"_intro_section_bg\":\"field_69a16c1a69a13\",\"intro_section_button\":\"\",\"_intro_section_button\":\"field_69a16c7e69a14\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"60\",\"right\":\"\",\"bottom\":\"60\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"50\",\"right\":\"\",\"bottom\":\"50\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"40\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\",\"content_alignment\":\"left\",\"_content_alignment\":\"field_69a6e5f3c5f77\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/slider-room-features-section {\"name\":\"acf/slider-room-features-section\",\"data\":{\"slider_images_0_image\":691,\"_slider_images_0_image\":\"field_69a7fa5bc950a\",\"slider_images_1_image\":494,\"_slider_images_1_image\":\"field_69a7fa5bc950a\",\"slider_images_2_image\":492,\"_slider_images_2_image\":\"field_69a7fa5bc950a\",\"slider_images\":3,\"_slider_images\":\"field_69a7ed273b8b9\",\"heading_text\":\"EXPLORE\",\"_heading_text\":\"field_69a7fa90c950b\",\"heading_level\":\"h2\",\"_heading_level\":\"field_69a7faafc950c\",\"feature_title\":\"\",\"_feature_title\":\"field_69a7fafbc950d\",\"feature_contents_0_content\":\"\",\"_feature_contents_0_content\":\"field_69a7fb25c950f\",\"feature_contents_1_content\":\"\",\"_feature_contents_1_content\":\"field_69a7fb25c950f\",\"feature_contents_2_content\":\"\",\"_feature_contents_2_content\":\"field_69a7fb25c950f\",\"feature_contents\":3,\"_feature_contents\":\"field_69a7fb15c950e\",\"button_button_link\":{\"title\":\"Reserve Room\",\"url\":\"https://webbooking.infodata.uk.com/Angel/WebBookingEngine/\",\"target\":\"_blank\"},\"_button_button_link\":\"field_69a7fb8bc9511\",\"button_aria_label\":\"AL Reserve Room\",\"_button_aria_label\":\"field_69a7fbb6c9512\",\"button_button_google_event_label\":\"GA Reserve Room\",\"_button_button_google_event_label\":\"field_69a7fbdac9513\",\"button_button_class\":\"trans-black-btn\",\"_button_button_class\":\"field_69a7fbe2c9514\",\"button\":\"\",\"_button\":\"field_69a7fb82c9510\",\"other_content\":\"In the area you have breathtaking Malham Cove with \\u2028its world famous limestone pavement, the picturesque waterfall at Janet’s Foss and pretty Yorkshire villages \\u2028of Appletreewick and Burnsall. Slightly further afield \\u2028you could challenge yourself to the Yorkshire three peaks, cross the border into Lancashire and discover the Forest of Bowland Area of Outstanding Natural Beauty or explore the smart shops of Ilkley or Harrogate.\\r\\n\\r\\nWe have 16 beautiful and individually designed \\u2028en-suite rooms.\",\"_other_content\":\"field_69abd6b28efba\",\"background_image\":442,\"_background_image\":\"field_69abd8559f282\",\"background_color\":\"\",\"_background_color\":\"field_69abd83ebba32\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a9134d82ebc\",\"padding\":{\"desktop\":{\"top\":\"60\",\"right\":\"\",\"bottom\":\"60\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"50\",\"right\":\"\",\"bottom\":\"50\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"40\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a9136e82ebd\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/google-map-section {\"name\":\"acf/google-map-section\",\"data\":{\"google_map\":{\"address\":\"The Angel at Hetton, Back Lane, Hetton, Skipton, UK\",\"lat\":54.02587219999999,\"lng\":-2.0598778,\"zoom\":14,\"place_id\":\"ChIJ4xnzvx31e0gRtti7Aj3ZaaY\",\"name\":\"The Angel at Hetton\",\"street_name\":\"Back Lane\",\"street_name_short\":\"Back Ln\",\"city\":\"Skipton\",\"state\":\"England\",\"post_code\":\"BD23 6LT\",\"country\":\"United Kingdom\",\"country_short\":\"GB\"},\"_google_map\":\"field_69abdd0c3414f\",\"map_address\":\"The Angel Inn,\\r\\nHetton, Near Skipton,\\r\\nNorth Yorkshire,\\r\\nBD23 6LT\",\"_map_address\":\"field_69abe5d357c44\",\"aria_labelledby\":\"AL - The Angel Inn\",\"_aria_labelledby\":\"field_69abe06b7af70\",\"aria_describedby\":\"AD -The Angel Inn\",\"_aria_describedby\":\"field_69abe07c7af71\",\"aria_description_content\":\"The Angel Inn,\\r\\nHetton, Near Skipton,\\r\\nNorth Yorkshire,\\r\\nBD23 6LT\\r\\n\\r\\n\",\"_aria_description_content\":\"field_69abe09c7af72\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69abde8e7af6e\",\"padding\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_padding\":\"field_69abde9b7af6f\"},\"align\":\"full\",\"mode\":\"edit\"} /-->', 'Location', '', 'publish', 'closed', 'closed', '', 'location', '', '', '2026-03-19 10:37:44', '2026-03-19 10:37:44', '', 0, 'http://localhost/punch-wp-angelathetton/?page_id=154', 0, 'page', '', 0),
