(408, 1, '2026-03-03 10:31:56', '2026-03-03 10:31:56', '<!-- wp:acf/full-width-banner-image-section {\"name\":\"acf/full-width-banner-image-section\",\"data\":{\"banner_image\":371,\"_banner_image\":\"field_69a511018ba0e\",\"section_bg\":\"\",\"_section_bg\":\"field_69a5180cdb4f0\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/introtext-section {\"name\":\"acf/introtext-section\",\"data\":{\"get_dynamic_heading_from_page_post\":\"0\",\"_get_dynamic_heading_from_page_post\":\"field_69a16b0f69a0f\",\"heading_text\":\"OUR STORY\",\"_heading_text\":\"field_69a16b5869a10\",\"heading_level\":\"h1\",\"_heading_level\":\"field_69a16b7269a11\",\"content\":\"Lorem ipsum dolor sit amet consectetur. Vestibulum amet consequat sit arcu ac. Vestibulum sit commodo fringilla duis leo id sem suscipit massa. Tempus mi malesuada eget viverra ipsum magna mauris dui. Bibendum vulputate egestas sed in pellentesque.\",\"_content\":\"field_69a16bf469a12\",\"intro_section_bg\":\"\",\"_intro_section_bg\":\"field_69a16c1a69a13\",\"intro_section_button\":\"\",\"_intro_section_button\":\"field_69a16c7e69a14\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"60\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"50\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"40\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/left-right-media-content-section {\"name\":\"acf/left-right-media-content-section\",\"data\":{\"sho