(516, 1, '2026-03-05 07:38:41', '2026-03-05 07:38:41', '<!-- wp:acf/full-width-banner-image-section {\"name\":\"acf/full-width-banner-image-section\",\"data\":{\"banner_image\":371,\"_banner_image\":\"field_69a511018ba0e\",\"section_bg\":\"\",\"_section_bg\":\"field_69a5180cdb4f0\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/introtext-section {\"name\":\"acf/introtext-section\",\"data\":{\"get_dynamic_heading_from_page_post\":\"0\",\"_get_dynamic_heading_from_page_post\":\"field_69a16b0f69a0f\",\"heading_text\":\"OUR STORY\",\"_heading_text\":\"field_69a16b5869a10\",\"heading_level\":\"h1\",\"_heading_level\":\"field_69a16b7269a11\",\"content\":\"Lorem ipsum dolor sit amet consectetur. Vestibulum amet consequat sit arcu ac. Vestibulum sit commodo fringilla duis leo id sem suscipit massa. Tempus mi malesuada eget viverra ipsum magna mauris dui. Bibendum vulputate egestas sed in pellentesque.\",\"_content\":\"field_69a16bf469a12\",\"intro_section_bg\":\"\",\"_intro_section_bg\":\"field_69a16c1a69a13\",\"intro_section_button\":\"\",\"_intro_section_button\":\"field_69a16c7e69a14\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"60\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"50\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"40\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/left-right-media-content-section {\"name\":\"acf/left-right-media-content-section\",\"data\":{\"show_left_side_image\":\"1\",\"_show_left_side_image\":\"field_69a57f529c686\",\"media_image\":374,\"_media_image\":\"field_69a582b55aa21\",\"title\":\"OUR FOOD\",\"_title\":\"field_69a582c45aa22\",\"heading_level\":\"h2\",\"_heading_level\":\"field_69a5830e5aa23\",\"content\":\"Since opening in September 2018, The Angel has received numerous awards including a Michelin star just 12 months after opening, five AA Rosettes (making history as the first restaurant in Yorkshire to receive such a distinction) and was placed number 2 in the National Restaurant Awards Top 100 Restaurants. In 2022 the restaurant received fourth place in the Top 50 Gastropubs, with chef patron Michael Wignall being crowned 2022 Chef of the Year.\",\"_content\":\"field_69a583845aa24\",\"intro_section_button_0_button_link\":{\"title\":\"Discover More\",\"url\":\"http://localhost/punch-wp-angelathetton/ten-course-tasting-lunch/\",\"target\":\"\"},\"_intro_section_button_0_button_link\":\"field_69a583db5aa26\",\"intro_section_button_0_aria_label\":\"Click AL\",\"_intro_section_button_0_aria_label\":\"field_69a583ec5aa27\",\"intro_section_button_0_button_google_event_label\":\"Click GA\",\"_intro_section_button_0_button_google_event_label\":\"field_69a583fe5aa28\",\"intro_section_button_0_button_class\":\"trans-black-btn\",\"_intro_section_button_0_button_class\":\"field_69a5840d5aa29\",\"intro_section_button_1_button_link\":{\"title\":\"Reserve a Table\",\"url\":\"https://webbooking.infodata.uk.com/Angel/WebBookingEngine/\",\"target\":\"\"},\"_intro_section_button_1_button_link\":\"field_69a583db5aa26\",\"intro_section_button_1_aria_label\":\"Click AL\",\"_intro_section_button_1_aria_label\":\"field_69a583ec5aa27\",\"intro_section_button_1_button_google_event_label\":\"Click GA\",\"_intro_section_button_1_button_google_event_label\":\"field_69a583fe5aa28\",\"intro_section_button_1_button_class\":\"trans-black-btn\",\"_intro_section_button_1_button_class\":\"field_69a5840d5aa29\",\"intro_section_butt