:\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"30\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"20\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\",\"content_alignment\":\"left\",\"_content_alignment\":\"field_69a6e5f3c5f77\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/container-width-two-column-image-section {\"name\":\"acf/container-width-two-column-image-section\",\"data\":{\"images_0_image\":544,\"_images_0_image\":\"field_69a97c662a9a5\",\"images_1_image\":545,\"_images_1_image\":\"field_69a97c662a9a5\",\"images\":2,\"_images\":\"field_69a97c3340d2a\",\"section_bg\":\"\",\"_section_bg\":\"field_69a97c3344717\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a97c33480fd\",\"padding\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"60\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"50\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a97c334a051\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/introtext-section {\"name\":\"acf/introtext-section\",\"data\":{\"get_dynamic_heading_from_page_post\":\"0\",\"_get_dynamic_heading_from_page_post\":\"field_69a16b0f69a0f\",\"heading_text\":\"\",\"_heading_text\":\"field_69a16b5869a10\",\"heading_level\":\"p\",\"_heading_level\":\"field_69a16b7269a11\",\"content\":\"\\u003cstrong\\u003eTERMS \\u0026amp; CONDITIONS:\\u003c/strong\\u003e\\r\\n20% off applies to stays on Monday, Thursday and Sunday evenings only, subject to availability. Offer valid to 31 March 2026.\\r\\nBookings must be made in advance, with a full prepayment taken at the time of booking. A 72 hour cancellation policy will apply.\",\"_content\":\"field_69a16bf469a12\",\"intro_section_bg\":\"\",\"_intro_section_bg\":\"field_69a16c1a69a13\",\"intro_section_button\":\"\",\"_intro_section_button\":\"field_69a16c7e69a14\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\",\"content_alignment\":\"left\",\"_content_alignment\":\"field_69a6e5f3c5f77\"},\"align\":\"full\",\"mode\":\"edit\"} /-->', '20% OFF 2-NIGHT GOURMET BREAKS', '', 'publish', 'open', 'closed', '', '20-off-2-night-gourmet-breaks', '', '', '2026-04-22 09:12:25', '2026-04-22 09:12:25', '', 0, 'http://localhost/punch-wp-angelathetton/?post_type=package&#038;p=588', 0, 'package', '', 0);
