(1186, 1, '2026-03-19 09:11:23', '2026-03-19 09:11:23', '<!-- wp:acf/full-width-title-banner-image-section {\"name\":\"acf/full-width-title-banner-image-section\",\"data\":{\"banner_image\":825,\"_banner_image\":\"field_69bba0688316f\",\"section_bg\":\"\",\"_section_bg\":\"field_69bba06886d28\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69bba0688a684\",\"padding\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_padding\":\"field_69bba0688e295\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/introtext-section {\"name\":\"acf/introtext-section\",\"data\":{\"get_dynamic_heading_from_page_post\":\"0\",\"_get_dynamic_heading_from_page_post\":\"field_69a16b0f69a0f\",\"heading_text\":\"WEDDINGS AT THE ANGEL\",\"_heading_text\":\"field_69a16b5869a10\",\"heading_level\":\"h1\",\"_heading_level\":\"field_69a16b7269a11\",\"content\":\"The Angel at Hetton sits in one of North Yorkshire’s most romantic settings. With the spectacular backdrop of the stunning Yorkshire Dales right on our doorstep, we are proud to offer the warmest of welcomes on this – your most special day. We have created a choice of two fabulous wedding packages. Whatever option you choose, you can be sure that you will be assigned a dedicated and experienced Wedding Coordinator who will work with you at every step of the way. Every detail will be taken care of. Fabulous cuisine and unsurpassed levels of service ensure the most unforgettable experience for you and your guests. You will enjoy exclusive use of The Angel Inn along with our twenty bedrooms and suites. Available from 11am to 11am. Our bedrooms are guaranteed to be available from 3pm.\",\"_content\":\"field_69a16bf469a12\",\"intro_section_bg\":\"\",\"_intro_section_bg\":\"field_69a16c1a69a13\",\"intro_section_button_0_button_link\":{\"title\":\"Enquire\",\"url\":\"mailto:reservations@angelhetton.co.uk\",\"target\":\"\"},\"_intro_section_button_0_button_link\":\"field_69a16d2669a15\",\"intro_section_button_0_aria_label\":\"Enquire\",\"_intro_section_button_0_aria_label\":\"field_69a16d3269a16\",\"intro_section_button_0_button_google_event_label\":\"Enquire\",\"_intro_section_button_0_button_google_event_label\":\"field_69a16d3f69a17\",\"intro_section_button_0_button_class\":\"trans-black-btn\",\"_intro_section_button_0_button_class\":\"field_69a280b5c732b\",\"intro_section_button\":1,\"_intro_section_button\":\"field_69a16c7e69a14\",\"margin\":{\"desktop\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"tablet\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"},\"mobile\":{\"top\":\"\",\"right\":\"\",\"bottom\":\"\",\"left\":\"\",\"linked\":\"1\",\"unit\":\"px\"}},\"_margin\":\"field_69a6b1a351481\",\"padding\":{\"desktop\":{\"top\":\"60\",\"right\":\"\",\"bottom\":\"60\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"tablet\":{\"top\":\"50\",\"right\":\"\",\"bottom\":\"50\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"},\"mobile\":{\"top\":\"40\",\"right\":\"\",\"bottom\":\"40\",\"left\":\"\",\"linked\":\"0\",\"unit\":\"px\"}},\"_padding\":\"field_69a6b1b451482\",\"content_alignment\":\"left\",\"_content_alignment\":\"field_69a6e5f3c5f77\"},\"align\":\"full\",\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/package-details-with-images-section {\"name\":\"acf/package-details-with-images-section\",\"data\":{\"main_heading_text\":\"CLASSIC WEDDING PACKAGE\",